def fibonacci(n)
	return n if n <= 1
	a, b = 0, 1
	(n - 1).times { a, b = b, a + b }
	b
end

class Stack
	def initialize
		@data = []
	end

	def push(item)
		@data.push(item)
		self
	end

	def pop
		raise "stack underflow" if empty?
		@data.pop
	end

	def empty?
		@data.empty?
	end
end

def two_sum(nums, target)
	seen = {}
	nums.each_with_index do |num, i|
		complement = target - num
		return [seen[complement], i] if seen.key?(complement)
		seen[num] = i
	end
	[]
end

def memoize(&block)
	cache = {}
	lambda do |*args|
		cache[args] ||= block.call(*args)
	end
end

fib = memoize { |n| n < 2 ? n : fib.call(n - 1) + fib.call(n - 2) }

